-- Every DateTime column becomes TIMESTAMPTZ(3) so an instant no longer depends on the session time zone.
-- Prisma wrote these columns as UTC wall-clock values, so they convert AT TIME ZONE 'UTC'. Values written by
-- a database default (now() in the server time zone) through raw SQL are converted from the server time zone.

-- Invoices generated by raw INSERT took "createdAt" from now() in the server time zone. Their lines were written
-- by Prisma in UTC in the same transaction, so the reading closest to the first line is the true instant.
ALTER TABLE "Invoice" ADD COLUMN "createdAtInstant" TIMESTAMPTZ(3);
-- A helper column, not an Invoice change: the snapshot guards stay off only for this backfill.
ALTER TABLE "Invoice" DISABLE TRIGGER USER;
UPDATE "Invoice" invoice SET "createdAtInstant" = CASE
  WHEN first_line.at IS NOT NULL AND abs(extract(epoch FROM (invoice."createdAt" AT TIME ZONE current_setting('TimeZone')) - (first_line.at AT TIME ZONE 'UTC')))
    < abs(extract(epoch FROM (invoice."createdAt" AT TIME ZONE 'UTC') - (first_line.at AT TIME ZONE 'UTC')))
  THEN invoice."createdAt" AT TIME ZONE current_setting('TimeZone')
  ELSE invoice."createdAt" AT TIME ZONE 'UTC' END
FROM (SELECT i."id", (SELECT min(line."createdAt") FROM "InvoiceLine" line WHERE line."schoolId" = i."schoolId" AND line."invoiceId" = i."id") AS at FROM "Invoice" i) first_line
WHERE first_line."id" = invoice."id";
ALTER TABLE "Invoice" ENABLE TRIGGER USER;

