-- Columns that were already TIMESTAMPTZ were written by Prisma as UTC wall-clock values without an offset, which
-- a non-UTC server session read as local time: each such instant is early by the server offset. The API now
-- connects with TimeZone=UTC; shift the stored rows back. On a UTC server these updates change nothing.
-- StudentPromotionalCoverage."issuedAt" comes from the database default and is already a true instant.
ALTER TABLE "CollectionRunCoverageSelection" DISABLE TRIGGER USER;
UPDATE "CollectionRunCoverageSelection" SET "createdAt" = ("createdAt" AT TIME ZONE current_setting('TimeZone')) AT TIME ZONE 'UTC';
ALTER TABLE "CollectionRunCoverageSelection" ENABLE TRIGGER USER;
ALTER TABLE "CoverageReversalRequest" DISABLE TRIGGER USER;
UPDATE "CoverageReversalRequest" SET "createdAt" = ("createdAt" AT TIME ZONE current_setting('TimeZone')) AT TIME ZONE 'UTC', "decidedAt" = ("decidedAt" AT TIME ZONE current_setting('TimeZone')) AT TIME ZONE 'UTC';
ALTER TABLE "CoverageReversalRequest" ENABLE TRIGGER USER;
