ALTER TABLE "StaffPhoto" ENABLE TRIGGER USER;
-- Ledger events: migration backfills are true instants and Prisma rows written before the ledger became
-- TIMESTAMPTZ were converted from UTC; only later Prisma rows are shifted. Coverage issue events copy their coverage.
ALTER TABLE "FinanceLedgerEvent" DISABLE TRIGGER USER;
UPDATE "FinanceLedgerEvent" SET "postedAt" = ("postedAt" AT TIME ZONE current_setting('TimeZone')) AT TIME ZONE 'UTC'
WHERE "type" <> 'COVERAGE_ISSUED' AND COALESCE("provenance" ->> 'backfill', 'false') <> 'true'
  AND "postedAt" >= COALESCE((SELECT min("finished_at") FROM "_prisma_migrations" WHERE "migration_name" = '20260926000002_finance_ledger_timestamptz_and_full_backfill'), '-infinity'::timestamptz)
    - (((now() AT TIME ZONE current_setting('TimeZone')) AT TIME ZONE 'UTC') - now());
UPDATE "FinanceLedgerEvent" event SET "postedAt" = coverage."issuedAt"
FROM "StudentPromotionalCoverage" coverage
WHERE event."type" = 'COVERAGE_ISSUED' AND event."schoolId" = coverage."schoolId" AND event."sourceKey" = coverage."id"::text;
ALTER TABLE "FinanceLedgerEvent" ENABLE TRIGGER USER;

-- "issuedAt" is now an instant: its Vietnam calendar date no longer needs the UTC wall-clock conversion.
DO $$
DECLARE definition text;
BEGIN
  definition := pg_get_functiondef('reject_invoice_snapshot_mutation'::regproc);
  IF position('((NEW."issuedAt" AT TIME ZONE ''UTC'') AT TIME ZONE ''Asia/Ho_Chi_Minh'')::date' IN definition) = 0 THEN
    RAISE EXCEPTION 'reject_invoice_snapshot_mutation no longer has the expected issuedAt conversion';
  END IF;
  EXECUTE replace(definition, '((NEW."issuedAt" AT TIME ZONE ''UTC'') AT TIME ZONE ''Asia/Ho_Chi_Minh'')::date', '(NEW."issuedAt" AT TIME ZONE ''Asia/Ho_Chi_Minh'')::date');
END;
$$;
